python3 - <<'EOF'
p='tests/app.test.js'
s=open(p).read()
s=s.replace("import { dispatch } from '../src/app.js';","import { dispatch, routes } from '../src/app.js';",1)
s+='''
// What each route answers when the thing it depends on fails: a fixed text, never the exception. A new route needs a row.
const INTERNAL = { status: 500, body: { error: 'internal error' } };
const onFailure = {
  'rooms-list': INTERNAL,
  'rooms-get': INTERNAL,
  'rooms-update': INTERNAL,
  'bookings-list': INTERNAL,
  'bookings-create': INTERNAL,
  'bookings-cancel': INTERNAL,
  'invoices-get': INTERNAL,
  'reminders-send': { status: 502, body: { message: 'could not send the reminders' } },
  'users-me': INTERNAL,
  health: INTERNAL,
};
const validRequest = {
  params: { id: 'r1' },
  query: { date: '2026-12-01' },
  body: { roomId: 'r1', date: '2026-12-01', name: 'Oak' },
  user: { id: 'u1' },
};
const SECRET = 'SQLITE_BUSY: database is locked (/var/lib/booking/db.sqlite)';
const failingWith = (thrown) =>
  Object.fromEntries(
    Object.entries(deps).map(([name, store]) => [
      name,
      Object.fromEntries(Object.keys(store).map((method) => [method, async () => { throw thrown; }])),
    ]),
  );

test('every route has a row in the failure table', () => {
  assert.deepEqual(Object.keys(onFailure).sort(), Object.keys(routes).sort());
});

for (const [name, expected] of Object.entries(onFailure)) {
  for (const [kind, thrown] of [['an Error', new Error(SECRET)], ['a string', SECRET]]) {
    test(`${name} answers a fixed text and logs the exception, when ${kind} is thrown`, async () => {
      const before = logged.length;
      const r = await dispatch(name, validRequest, failingWith(thrown));
      assert.deepEqual(r, expected);
      assert.equal(logged.length, before + 1);
      assert.equal(logged.at(-1).where, name);
      assert.match(logged.at(-1).detail, /SQLITE_BUSY: database is locked \\(\\/var\\/lib\\/booking\\/db\\.sqlite\\)/);
    });
  }
}
'''
open(p,'w').write(s)
EOF
